  function restoreDraft(){const key=draftKey();if(!key||S.comparison||S.restoredDrafts?.has(key))return false;(S.restoredDrafts??=new Set()).add(key);let saved;try{saved=JSON.parse(sessionStorage.getItem(key)||'null');}catch{return false;}if(!saved?.draft||!Array.isArray(saved.editors))return false;S.draft=saved.draft;S.editors=new Map(saved.editors);S.pending=new Map(saved.pending||[]);S.boardOrders=new Map(saved.boardOrders||[]);S.returnedRuns=new Map(saved.returnedRuns||[]);S.dirty=true;S.preview=null;if(S.draft.base_version!==S.workspace.version||S.draft.day_version!==(S.workspace.day?.version??0)){S.conflict=true;$('conflict').hidden=false;}render();controls();return true;}
